const list = Array.isArray($json) ? $json : [];
const withRecordings = list.filter(m => m.recording_url && m.status === 'ended');
return withRecordings.map(m => ({
  json: {
    body: {
      title: m.title,
      calendar_event_id: m.calendar_event_id || m.meeting_id,
      start_time: m.start_time,
      end_time: m.end_time,
      organizer_email: m.organizer_email || '',
      participant_emails: m.participant_emails || [],
      participant_master_ids: m.participant_master_ids || [],
      recording_url: m.recording_url
    }
  }
}));

const input = $input.first();
const body = input.json.body || input.json || {};
const hasBinary = Boolean(input.binary && (input.binary.file || input.binary.data));

return [{
  json: {
    title: body.title || 'Созвон Google Meet',
    calendar_event_id: body.calendar_event_id || '',
    start_time: body.start_time || new Date().toISOString(),
    end_time: body.end_time || new Date().toISOString(),
    organizer_master_id: body.organizer_master_id || null,
    organizer_email: body.organizer_email || '',
    participant_master_ids: Array.isArray(body.participant_master_ids) ? body.participant_master_ids : [],
    participant_emails: Array.isArray(body.participant_emails) ? body.participant_emails : [],
    recording_url: body.recording_url || '',
    audio_base64: body.audio_base64 || '',
    file_name: body.file_name || 'google_meet_recording.m4a',
    has_binary: hasBinary
  },
  binary: input.binary || {}
}];

const item = $input.first();
const meta = $('Normalize Meet Metadata').item.json;

if (item.binary && (item.binary.file || item.binary.data)) {
  const bin = item.binary.file || item.binary.data;
  return [{ json: meta, binary: { file: bin } }];
}

if (meta.audio_base64) {
  const buf = Buffer.from(meta.audio_base64, 'base64');
  const prepared = await this.helpers.prepareBinaryData(buf, meta.file_name || 'google_meet_recording.m4a', 'audio/mp4');
  return [{ json: meta, binary: { file: prepared } }];
}

throw new Error('Не передан аудиофайл, audio_base64 или recording_url записи созвона.');

const stt = $json || {};
if (stt.success === false || !String(stt.text || '').trim()) {
  throw new Error('STT failed or empty transcript: ' + (stt.error || 'empty text'));
}
return [{ json: stt }];

