const meta = $('Normalize Meet Metadata').item.json;
const stt = $('Whisper Transcribe (STT)').item.json;
const rawLlmText = $json.response?.text || $json.response?.Text || '';

let parsed = null;
try {
  const start = rawLlmText.indexOf('{');
  const end = rawLlmText.lastIndexOf('}');
  if (start >= 0 && end > start) {
    parsed = JSON.parse(rawLlmText.slice(start, end + 1));
  }
} catch {
  parsed = null;
}

const transcript = stt.text || '';
const summary = parsed?.summary || rawLlmText || transcript.slice(0, 600);
const title = parsed?.title || meta.title;
const decisions = Array.isArray(parsed?.decisions) ? parsed.decisions : [];
const actionItems = Array.isArray(parsed?.action_items) ? parsed.action_items : [];

return [{
  json: {
    title,
    calendar_event_id: meta.calendar_event_id || null,
    start_time: meta.start_time,
    end_time: meta.end_time,
    organizer_master_id: meta.organizer_master_id,
    organizer_email: meta.organizer_email || null,
    participant_master_ids: meta.participant_master_ids,
    participant_emails: meta.participant_emails,
    raw_transcript: transcript,
    summary,
    decisions,
    action_items: actionItems
  }
}];
